int enA = 9;
int in1 = 8;
int in2 = 7;

void setup() {
  pinMode(enA, OUTPUT);
  pinMode(in1, OUTPUT);
  pinMode(in2, OUTPUT);
}

void loop() {
  // Плавный разгон вперёд
  digitalWrite(in1, HIGH);
  digitalWrite(in2, LOW);
  for (int speed = 0; speed <= 150; speed++) {
    analogWrite(enA, speed);
    delay(20); // можно менять под нужную скорость разгона
  }
  delay(3000);

  // Плавная остановка
  for (int speed = 150; speed >= 0; speed--) {
    analogWrite(enA, speed);
    delay(20);
  }
  delay(1000);

  // Разворот и плавный разгон назад
  digitalWrite(in1, LOW);
  digitalWrite(in2, HIGH);
  for (int speed = 0; speed <= 150; speed++) {
    analogWrite(enA, speed);
    delay(20);
  }
  delay(3000);

  // Плавная остановка снова
  for (int speed = 150; speed >= 0; speed--) {
    analogWrite(enA, speed);
    delay(20);
  }
  delay(1000);
}
